function sanitizePostgresConnectionString(rawUrl) {
  const trimmed = (rawUrl || "").trim();
  const match = /^(postgres(?:ql)?):\/\/([^:]+):(.+)@([^@/]+(?::\d+)?\/[^?#]*)(.*)$/i.exec(
    trimmed
  );
  let normalized = trimmed;
  if (match) {
    const [, proto, user, rawPass, hostAndDb] = match;
    let cleanPass = rawPass;
    if (cleanPass.startsWith("[") && cleanPass.endsWith("]")) {
      cleanPass = cleanPass.slice(1, -1);
    }
    try {
      cleanPass = decodeURIComponent(cleanPass);
    } catch {
    }
    const encodedPass = encodeURIComponent(cleanPass);
    normalized = `${proto}://${user}:${encodedPass}@${hostAndDb}`;
  }
  try {
    const parsed = new URL(normalized);
    parsed.searchParams.delete("sslmode");
    parsed.searchParams.delete("pgbouncer");
    parsed.searchParams.delete("supa");
    parsed.searchParams.delete("uselibpqcompat");
    return parsed.toString();
  } catch {
    return normalized.replace(/([?&])sslmode=[^&]+(&|$)/i, "$1").replace(/[?&]$/, "");
  }
}
function getConnectionString() {
  const raw = process.env.SUPABASE_DB_URL || process.env.DATABASE_URL || process.env.POSTGRES_URL || process.env.POSTGRES_URL_NON_POOLING || process.env.POSTGRES_PRISMA_URL || process.env.NEON_DATABASE_URL;
  return raw ? sanitizePostgresConnectionString(raw.trim()) : void 0;
}
function hasDatabaseConfig() {
  return Boolean(
    getConnectionString() || process.env.SQL_HOST || process.env.PGHOST
  );
}
var createPool = () => {
  if (!global._postgresPool) {
    const connectionString = getConnectionString();
    const poolMax = process.env.VERCEL ? 2 : 10;
    global._postgresPool = connectionString ? new Pool({
      connectionString,
      ssl: connectionString.includes("localhost") || connectionString.includes("127.0.0.1") ? void 0 : { rejectUnauthorized: false },
      max: poolMax,
      idleTimeoutMillis: 1e4,
      connectionTimeoutMillis: 1e4
    }) : new Pool({
      host: process.env.SQL_HOST || process.env.PGHOST,
      user: process.env.SQL_USER || process.env.PGUSER,
      password: process.env.SQL_PASSWORD || process.env.PGPASSWORD,
      database: process.env.SQL_DB_NAME || process.env.PGDATABASE,
      port: process.env.PGPORT ? Number(process.env.PGPORT) : void 0,
      max: poolMax,
      idleTimeoutMillis: 1e4,
      connectionTimeoutMillis: 1e4
    });
    global._postgresPool.on("error", (err) => {
      console.error("Unexpected error on idle SQL pool client:", err);
    });
  }
  return global._postgresPool;
};
