    const allRoles = await db.select().from(roles);
    const studentRole = allRoles.find((r) => r.name === "mahasiswa") || allRoles[0];
    const sanitizedSlug = cleanNim.toLowerCase().replace(/[^a-z0-9._-]/g, "") || `${Date.now()}`;
    let targetEmail = (data.email || "").trim().toLowerCase();
    if (!targetEmail) {
      targetEmail = `${sanitizedSlug}@student.unikma.ac.id`;
    }
    const existingEmail = await db.select().from(users).where(eq(users.email, targetEmail));
    if (existingEmail.length > 0) {
      if ((data.email || "").trim()) {
        throw new Error(`Email ${targetEmail} sudah digunakan akun lain.`);
      }
      targetEmail = `${sanitizedSlug}-${Date.now()}@student.unikma.ac.id`;
    }
