async function updateEssayScoreAndVerifyResult(data) {
  try {
    const existingRows = await db.select().from(examResults).where(eq(examResults.id, data.resultId));
    const current = existingRows[0];
    if (!current) {
      throw new Error("Hasil ujian tidak ditemukan.");
    }
    const finalScore = Math.min(
      100,
      Math.max(0, current.objectiveScore + data.essayScore)
    );
    const gradeLetter = computeGradeLetter(finalScore);
    const updated = await db.update(examResults).set({
      essayScore: data.essayScore,
      finalScore,
      gradeLetter,
      verificationStatus: data.verificationStatus,
      isPublished: data.isPublished
    }).where(eq(examResults.id, data.resultId)).returning();
    return updated[0];
  } catch (error) {
    console.error("Failed to update essay score:", error);
    throw new Error("Gagal memperbarui nilai esai dan verifikasi.", {
      cause: error
    });
  }
}
async function verifyViolationRecord(data) {
  try {
    const updated = await db.update(violationLogs).set({
      actionTaken: data.actionTaken,
      verifiedByAdmin: data.verifiedByAdmin
    }).where(eq(violationLogs.id, data.violationId)).returning();
    return updated[0];
  } catch (error) {
    console.error("Failed to verify violation:", error);
    throw new Error("Gagal memverifikasi log pelanggaran.", { cause: error });
  }
}
