dotenv.config();
var PORT = Number(process.env.PORT) || 3e3;
var app = express();
var httpServer = createServer(app);
app.use(express.json({ limit: "20mb" }));
var uploadsDir = process.env.VERCEL ? path3.join("/tmp", "uploads") : path3.resolve(process.cwd(), "uploads");
app.use("/uploads", express.static(uploadsDir, { maxAge: "1d" }));
app.use("/api", (req, res, next) => {
  if (!req.path.endsWith("/image")) {
    res.setHeader(
      "Cache-Control",
      "no-store, no-cache, must-revalidate, proxy-revalidate"
    );
    res.setHeader("Pragma", "no-cache");
  }
  next();
});
app.get("/api/health", async (_req, res) => {
  const conn = getConnectionString();
  const configured = hasDatabaseConfig();
  let dbReachable = false;
  if (configured) {
    try {
      await pool.query("SELECT 1");
      dbReachable = true;
    } catch {
      dbReachable = false;
    }
  }
  const mode = configured ? conn?.includes("supabase") ? "supabase" : "postgres" : process.env.VERCEL ? "browser-fallback" : "local-file-db";
  res.json({ ok: true, mode, dbReachable });
});
app.use("/api", (req, res, next) => {
  if (!hasDatabaseConfig()) {
    if (process.env.VERCEL) {
      return res.status(503).json({
        vercelFallbackRequired: true,
        error: "Database eksternal belum dikonfigurasi pada environment ini."
      });
    }
    return handleLocalFileApiRequest(req, res);
  }
  next();
});
var wss = null;
if (!process.env.VERCEL) {
  wss = new WebSocketServer({
    server: httpServer,
    path: "/ws-proctoring"
  });
  wss.on("connection", (ws) => {
    ws.send(
      JSON.stringify({
        type: "proctoring:connected",
        payload: { status: "Real-Time Proctoring Channel Active" },
        timestamp: (/* @__PURE__ */ new Date()).toISOString()
      })
    );
  });
}
var broadcastEvent = (type, payload) => {
  if (!wss) return;
  const message = JSON.stringify({
    type,
    payload,
    timestamp: (/* @__PURE__ */ new Date()).toISOString()
  });
  wss.clients.forEach((client) => {
    if (client.readyState === WebSocket.OPEN) {
      client.send(message);
    }
  });
};
