registerRoutes();
async function startServer() {
  if (process.env.NODE_ENV !== "production") {
    const { createServer: createViteServer } = await import("vite");
    const vite = await createViteServer({
      server: { middlewareMode: true },
      appType: "spa"
    });
    app.use(vite.middlewares);
  } else {
    const cwdDist = path3.join(process.cwd(), "dist");
    const fileDirDist = path3.resolve(
      path3.dirname(fileURLToPath(import.meta.url)),
      "dist"
    );
    const distPath = fs3.existsSync(cwdDist) ? cwdDist : fileDirDist;
    app.use(express.static(distPath));
    app.get("*", (_req, res) => {
      res.sendFile(path3.join(distPath, "index.html"));
    });
  }
  httpServer.listen(PORT, "0.0.0.0", () => {
    console.log(`MazCodeID SMART CBT Server running on http://0.0.0.0:${PORT}`);
  });
}
if (!process.env.VERCEL) {
  startServer();
}
var server_default = app;
export {
  app,
  server_default as default
};
